WITH not_flagged AS (SELECT s.* FROM accounts s WHERE EXISTS (SELECT 1 FROM transactions x WHERE x.account_id = s.id AND x.txn_type = 'CREDIT')) SELECT id, customer_id, account_type, opened_date, CASE WHEN account_type RLIKE '^(SAVINGS|CREDIT)$' THEN 'GROUP_B' WHEN account_type RLIKE '^(CHECKING|LOAN)$' THEN 'OTHER_ZONE' ELSE 'GROUP_A' END AS account_type_zone FROM not_flagged ORDER BY id ASC
